---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const attachmentMediaVariants = cva(
  "bg-muted text-foreground w-10 rounded-lg group-data-[size=sm]/attachment:w-8 group-data-[size=xs]/attachment:w-7 group-data-[size=xs]/attachment:rounded-md [&_svg:not([class*='size-'])]:size-4 group-data-[size=xs]/attachment:[&_svg:not([class*='size-'])]:size-3.5 group-data-[orientation=vertical]/attachment:w-full group-data-[orientation=vertical]/attachment:[&_svg:not([class*='size-'])]:size-6 group-data-[orientation=vertical]/attachment:*:data-[slot=spinner]:size-6! group-data-[state=error]/attachment:bg-destructive/10 group-data-[state=error]/attachment:text-destructive relative flex aspect-square shrink-0 items-center justify-center overflow-hidden [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        icon: "",
        image:
          "opacity-60 group-data-[state=idle]/attachment:opacity-100 group-data-[state=done]/attachment:opacity-100 *:[img]:aspect-square *:[img]:w-full *:[img]:object-cover",
      },
    },
    defaultVariants: {
      variant: "icon",
    },
  }
)

type Props = HTMLAttributes<"div"> &
  VariantProps<typeof attachmentMediaVariants>

const { class: className, variant = "icon", ...props } = Astro.props
---

<div
  data-slot="attachment-media"
  data-variant={variant}
  class={cn(attachmentMediaVariants({ variant }), className)}
  {...props}
>
  <slot />
</div>

---
import type { HTMLTag, Polymorphic } from "astro/types"

import { cn } from "@/lib/utils"

type Props<Tag extends HTMLTag = "button"> = Polymorphic<{ as: Tag }>

const {
  as: Tag = "href" in Astro.props ? "a" : "button",
  class: className,
  ...props
} = Astro.props

const attributes: Record<string, unknown> = { ...props }
if (Tag === "button") attributes.type ??= "button"
---

<Tag
  data-slot="attachment-trigger"
  class={cn("absolute inset-0 z-10 outline-none", className)}
  {...attributes}
>
  <slot />
</Tag>

---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const attachmentVariants = cva(
  "rounded-2xl w-fit focus-within:ring-1 focus-within:ring-ring/30 group/attachment bg-card text-card-foreground has-[>a,>button]:hover:bg-muted/50 data-[state=error]:border-destructive/30 relative flex max-w-full min-w-0 shrink-0 flex-wrap border transition-colors data-[state=idle]:border-dashed",
  {
    variants: {
      size: {
        default: "gap-2 has-data-[slot=attachment-content]:px-2.5 has-data-[slot=attachment-content]:py-2 has-data-[slot=attachment-media]:p-2 text-sm",
        sm: "gap-2.5 has-data-[slot=attachment-content]:px-2 has-data-[slot=attachment-content]:py-1.5 has-data-[slot=attachment-media]:p-1.5 text-xs",
        xs: "gap-1.5 has-data-[slot=attachment-content]:px-1.5 has-data-[slot=attachment-content]:py-1 has-data-[slot=attachment-media]:p-1 text-xs rounded-xl",
      },
      orientation: {
        horizontal: "min-w-40 items-center",
        vertical: "w-24 has-data-[slot=attachment-content]:w-30 flex-col",
      },
    },
    defaultVariants: {
      size: "default",
      orientation: "horizontal",
    },
  }
)

type Props = HTMLAttributes<"div"> &
  VariantProps<typeof attachmentVariants> & {
    state?: "idle" | "uploading" | "processing" | "error" | "done"
  }

const {
  class: className,
  state = "done",
  size = "default",
  orientation = "horizontal",
  ...props
} = Astro.props
---

<div
  data-slot="attachment"
  data-state={state}
  data-size={size}
  data-orientation={orientation}
  class={cn(attachmentVariants({ size, orientation }), className)}
  {...props}
>
  <slot />
</div>
